import React, { useState } from 'react';
import PropTypes from 'prop-types';
import { Container, ListGroup, ListGroupItem, Button, Spinner } from 'reactstrap';
import SockJS from 'sockjs-client';
import { Client } from '@stomp/stompjs';

// core components
import Header from '../../components/header/header.jsx';
import HeaderBanner from '../../components/banner/banner.jsx';
import Footer from '../../components/footer/footer.jsx';

// sections for this page
import Buttons from './sections/buttons.jsx';

const BASE_URL = 'http://your-api-url.com'; // 여기에 실제 API URL을 넣으세요

const ChatList = ({ toggleChat }) => {
    const [stompClient, setStompClient] = useState(null);
    const [chatsData, setChatsData] = useState([]);
    const [userId, setUserId] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Fetch the user ID from localStorage
        const id = localStorage.getItem('userId');
        setUserId(id);
        fetchChats(id);

        const socket = new SockJS(`${BASE_URL}/ws`);
        const client = new Client({
            webSocketFactory: () => socket,
            debug: function (str) {
                console.log(str);
            },
            reconnectDelay: 5000,
        });

        client.onConnect = () => {
            setStompClient(client);
            client.subscribe('/topic/chats', (msg) => {
                if (msg.body) {
                    setChatsData(JSON.parse(msg.body));
                }
            });
        };

        client.activate();

        return () => {
            if (client) {
                client.deactivate();
            }
        };
    }, []);

    const fetchChats = (id) => {
        fetch(`${BASE_URL}/api/chats?userId=${id}`)
            .then((response) => response.json())
            .then((data) => {
                setChatsData(data);
                setLoading(false);
            })
            .catch((error) => {
                console.error('Error fetching chat data:', error);
                setLoading(false);
            });
    };

    const renderChatListItem = (item) => {
        const otherUserId = item.fromId === userId ? item.toId : item.fromId;

        return (
            <ListGroupItem key={item.id} className="d-flex justify-content-between align-items-center">
                <div>
                    <strong>{otherUserId}</strong>
                    <p>{item.lastMessage}</p>
                    <small>{new Date(item.time).toLocaleString()}</small>
                </div>
                <Button color="primary" onClick={() => toggleChat(item.id, otherUserId)}>
                    채팅하기
                </Button>
            </ListGroupItem>
        );
    };

    return (
        <Container>
            {loading ? (
                <Spinner color="primary" />
            ) : chatsData.length > 0 ? (
                <ListGroup>{chatsData.map((item) => renderChatListItem(item))}</ListGroup>
            ) : (
                <div className="text-center">
                    <p>채팅 내역이 없습니다</p>
                </div>
            )}
        </Container>
    );
};

const ChatPage = ({ toggleChat }) => {
    return (
        <div
            className="chat-page"
            style={{
                position: 'fixed', // 채팅 페이지 고정
                bottom: 90,
                right: 30,
                width: '450px', // 채팅창 크기 조절
                height: '60%',
                backgroundColor: '#fff', // 배경색
                border: '1px solid #ccc', // 테두리
                padding: '10px',
                zIndex: 1000, // 다른 요소 위에 표시
                borderRadius: '15px', // 모서리 둥글게
                // display: showChat ? 'block' : 'none', // 채팅창 보이기/숨기기
            }}
        >
            <ChatList toggleChat={toggleChat} />
        </div>
    );
};

const Components = () => {
    const [showChatPage, setShowChatPage] = useState(false);
    const [currentChat, setCurrentChat] = useState(null);

    const toggleChatPage = () => {
        console.log('Chat page visibility:', !showChatPage); // 토글 상태 로그
        setShowChatPage(!showChatPage);
    };

    const toggleChat = (chatId, otherUserId) => {
        setCurrentChat({ chatId, otherUserId });
        setShowChatPage(true);
    };

    return (
        <div id="main-wrapper">
            <Header />
            <div className="page-wrapper">
                <div className="container-fluid">
                    <HeaderBanner />
                    <Buttons />
                    <button className="fixed-chat-button" onClick={toggleChatPage}>
                        채팅창 이동
                    </button>
                    {showChatPage && <ChatPage toggleChat={toggleChat} />} {/* 조건부 렌더링 */}
                </div>
            </div>
            <Footer />
        </div>
    );
};

Components.propTypes = {
    classes: PropTypes.object,
};

export default Components;
